using System;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using Xunit;
namespace RPCore.Tests
{
    public class HalloweenTests
    {
        static HalloweenOptions C()=>HalloweenOptions.Defaults();
        static WalletData W()=>new WalletData{Bank=12345,Cash=777};
        static WalletData Begin(){var w=W();Assert.True(HalloweenTransactions.Begin(w,"ride",C(),()=>{},out _));return w;}
        static HalloweenRun Run(WalletData w){var p=w.Halloween.Pending;return new HalloweenRun(p.Id,p.Options,p.Progress);}
        static HalloweenRun Drive(WalletData w){var r=Run(w);Assert.True(r.StartDriving(true));Assert.True(HalloweenTransactions.Checkpoint(w,"ride",r.Progress,()=>{},out _));return r;}
        [Fact]public void DefaultsUseReferenceRomeroStartDestinationAndPulseRules(){var c=C();Assert.True(c.Valid);Assert.Equal("romero",c.HearseModel);Assert.Equal(232.1685f,c.Start.X);Assert.Equal(-1389.492f,c.Start.Y);Assert.Equal(242.2843f,c.Hearse.X);Assert.Equal(78.73449f,c.Hearse.Heading);Assert.Equal(-1655.124f,c.Destination.X);Assert.Equal(-221.2749f,c.Destination.Y);Assert.Equal(180,c.SecondsLimit);Assert.Equal(8,c.PulseCooldownSeconds);Assert.Equal(12,c.PulseRadius);Assert.Equal(27,c.PulseSpeed);Assert.Equal(1500,c.RetaskMilliseconds);Assert.Equal(2800,c.RamCooldownMilliseconds);Assert.Equal(36,c.RamRange);}
        [Fact]public void LegacySaveStaysOptionalUntilExplicitStartOrPreference(){var w=JsonConvert.DeserializeObject<WalletData>("{\"Bank\":50,\"Cash\":5,\"Future\":42}");Assert.Null(w.Halloween);Assert.True(HalloweenTransactions.Configure(w,false,()=>{},out _));Assert.False(w.Halloween.Scares);Assert.Equal(0,w.Halloween.Started);Assert.Equal(50,w.Bank);Assert.Equal(5,w.Cash);Assert.Equal(42,(int)w.Extra["Future"]);}
        [Fact]public void NewAttemptHasDetachedOptionsAndNoMoneyChange(){var w=W();var c=C();HalloweenTransactions.Begin(w,"ride",c,()=>{},out _);c.SecondsLimit=600;c.Start.X=1;Assert.Equal(180,w.Halloween.Pending.Options.SecondsLimit);Assert.Equal(232.1685f,w.Halloween.Pending.Options.Start.X);Assert.True(w.Halloween.Valid);Assert.Equal(12345,w.Bank);Assert.Equal(777,w.Cash);}
        [Fact]public void CannotOverwritePendingOrReuseRecordedId(){var w=Begin();Assert.False(HalloweenTransactions.Begin(w,"another",C(),()=>throw new Exception(),out _));Assert.False(HalloweenTransactions.Configure(w,false,()=>throw new Exception(),out _));Assert.True(HalloweenTransactions.Finish(w,"ride","interrupted",100,null,()=>{},out _));Assert.False(HalloweenTransactions.Begin(w,"ride",C(),()=>throw new Exception(),out _));}
        [Fact]public void ClockStartsOnlyForOwnDriverAndOnlyCountsWorldTime(){var w=Begin();var r=Run(w);r.Tick(1000,true);Assert.Equal(0,r.Progress.Elapsed);Assert.False(r.StartDriving(false));Assert.True(r.StartDriving(true));Assert.False(r.StartDriving(true));r.Tick(1000,true);r.Tick(1000,false);r.Tick(1001,true);r.Tick(-1,true);Assert.Equal(1000,r.Progress.Elapsed);}
        [Fact]public void AtDeadlineDeliveryAndPulseAreRejected(){var w=Begin();var r=Drive(w);for(int i=0;i<180;i++)r.Tick(1000,true);Assert.Equal(HalloweenStage.Failed,r.Stage);Assert.False(r.Deliver(true,true,0,0));Assert.False(r.Pulse());Assert.True(HalloweenTransactions.Checkpoint(w,"ride",r.Progress,()=>{},out _));Assert.True(HalloweenTransactions.Finish(w,"ride","failed",20,null,()=>{},out _));Assert.Equal(1,w.Halloween.Failed);}
        [Fact]public void PulseRequiresRunningAndEightActiveSecondsBetweenUses(){var w=Begin();var r=Run(w);Assert.False(r.Pulse());r.StartDriving(true);Assert.True(r.Pulse());Assert.Equal(8000,r.Progress.NextPulse);Assert.False(r.Pulse());for(int i=0;i<7;i++)r.Tick(1000,true);Assert.False(r.Pulse());r.Tick(1000,true);Assert.True(r.Pulse());Assert.Equal(2,r.Progress.Pulses);Assert.Equal(16000,r.Progress.NextPulse);}
        [Fact]public void SavedPulseReplayIsIdempotentAndCountersStayExact(){var w=Begin();var r=Drive(w);r.Pulse();int saves=0;Assert.True(HalloweenTransactions.Checkpoint(w,"ride",r.Progress,()=>saves++,out bool changed));Assert.True(changed);Assert.True(HalloweenTransactions.Checkpoint(w,"ride",r.Progress,()=>throw new Exception(),out changed));Assert.False(changed);Assert.Equal(1,w.Halloween.TotalPulses);w=JsonConvert.DeserializeObject<WalletData>(JsonConvert.SerializeObject(w));r=Run(w);Assert.False(r.Pulse());Assert.Equal(1,saves);Assert.Equal(12345,w.Bank);}
        [Fact]public void CheckpointRejectsTimeRollbackPulseResetAndUnchargedPulse(){var w=Begin();var r=Drive(w);r.Pulse();HalloweenTransactions.Checkpoint(w,"ride",r.Progress,()=>{},out _);var p=JsonConvert.DeserializeObject<HalloweenProgress>(JsonConvert.SerializeObject(r.Progress));p.Pulses=0;p.NextPulse=0;Assert.False(HalloweenTransactions.Checkpoint(w,"ride",p,()=>throw new Exception(),out _));p=r.Progress;p.Pulses++;Assert.False(HalloweenTransactions.Checkpoint(w,"ride",p,()=>throw new Exception(),out _));Assert.False(HalloweenTransactions.Checkpoint(w,null,p,()=>throw new Exception(),out _));}
        [Fact]public void LostCheckpointCanAdvanceElapsedWithoutResettingCooldown(){var w=Begin();var r=Drive(w);r.Pulse();HalloweenTransactions.Checkpoint(w,"ride",r.Progress,()=>{},out _);for(int i=0;i<9;i++)r.Tick(1000,true);Assert.True(HalloweenTransactions.Checkpoint(w,"ride",r.Progress,()=>{},out _));Assert.Equal(8000,w.Halloween.Pending.Progress.NextPulse);Assert.True(r.Pulse());Assert.True(HalloweenTransactions.Checkpoint(w,"ride",r.Progress,()=>{},out _));Assert.Equal(17000,w.Halloween.Pending.Progress.NextPulse);}
        [Fact]public void ArrivalNeedsActualOwnStoppedDriverBeforeDeadline(){var w=Begin();var r=Drive(w);r.Tick(1000,true);Assert.False(r.Deliver(false,true,0,0));Assert.False(r.Deliver(true,false,0,0));Assert.False(r.Deliver(true,true,.5f,0));Assert.False(r.Deliver(true,true,0,5.1f));Assert.True(r.Deliver(true,true,0,5));Assert.False(r.Deliver(true,true,0,0));Assert.True(HalloweenTransactions.Checkpoint(w,"ride",r.Progress,()=>{},out _));Assert.True(HalloweenTransactions.Finish(w,"ride","completed",73,r,()=>{},out _));Assert.Equal(1,w.Halloween.Completed);Assert.Equal(73,w.Halloween.History[0].Condition);Assert.Equal(12345,w.Bank);Assert.Equal(777,w.Cash);}
        [Fact]public void RunningOrMismatchedProofCannotComplete(){var w=Begin();var r=Drive(w);Assert.False(HalloweenTransactions.Finish(w,"ride","completed",100,r,()=>throw new Exception(),out _));r.Deliver(true,true,0,0);var fake=new HalloweenRun("another",C(),r.Progress);fake.Deliver(true,true,0,0);Assert.False(HalloweenTransactions.Finish(w,"ride","completed",100,fake,()=>throw new Exception(),out _));}
        [Theory][InlineData("completed")][InlineData("failed")][InlineData("interrupted")]
        public void AllOutcomesRecordedOnceWithNoFinancialReward(string outcome){var w=Begin();var r=Drive(w);r.Tick(1000,true);if(outcome=="completed")r.Deliver(true,true,0,0);HalloweenTransactions.Checkpoint(w,"ride",r.Progress,()=>{},out _);int saves=0;Assert.True(HalloweenTransactions.Finish(w,"ride",outcome,75,r,()=>saves++,out bool changed));Assert.True(changed);Assert.True(HalloweenTransactions.Finish(w,"ride",outcome,75,r,()=>throw new Exception(),out changed));Assert.False(changed);Assert.Equal(1,saves);Assert.Null(w.Halloween.Pending);Assert.Equal(12345,w.Bank);Assert.Equal(777,w.Cash);Assert.True(w.Halloween.Valid);}
        [Fact]public void ReloadedPendingIsInterruptedWithoutRespawnOrPayout(){var w=Begin();var r=Drive(w);r.Tick(1000,true);HalloweenTransactions.Checkpoint(w,"ride",r.Progress,()=>{},out _);w=JsonConvert.DeserializeObject<WalletData>(JsonConvert.SerializeObject(w));Assert.True(HalloweenTransactions.Finish(w,"ride","interrupted",0,null,()=>{},out _));Assert.Null(w.Halloween.Pending);Assert.Equal(1000,w.Halloween.History[0].Elapsed);Assert.Equal(0,w.Halloween.Completed);}
        [Theory][InlineData("configure")][InlineData("begin")][InlineData("checkpoint")][InlineData("pulse")][InlineData("finish")]
        public void SaveFailureRollsBackAllJournalChanges(string operation){var w=operation=="configure" || operation=="begin"?W():Begin();var r=w.Halloween?.Pending!=null?Drive(w):null;if(operation=="pulse")r.Pulse();if(operation=="checkpoint")r.Tick(1000,true);string before=JsonConvert.SerializeObject(w);Action fail=()=>throw new InvalidOperationException();Assert.Throws<InvalidOperationException>(()=>{if(operation=="configure")HalloweenTransactions.Configure(w,false,fail,out _);if(operation=="begin")HalloweenTransactions.Begin(w,"ride",C(),fail,out _);if(operation=="checkpoint" || operation=="pulse")HalloweenTransactions.Checkpoint(w,"ride",r.Progress,fail,out _);if(operation=="finish")HalloweenTransactions.Finish(w,"ride","interrupted",70,null,fail,out _);});Assert.Equal(before,JsonConvert.SerializeObject(w));}
        [Fact]public void UnknownMetadataAndOtherSystemsSurviveJournalUpdates(){var w=Begin();var j=JObject.FromObject(w);j["FutureWallet"]=42;j["Halloween"]["FutureBook"]="keep";j["Halloween"]["Pending"]["Options"]["FutureOptions"]=77;j["Halloween"]["Pending"]["Progress"]["FutureProgress"]=88;w=j.ToObject<WalletData>();w.StudioHeist=new StudioHeistData();w.Custody=new CustodyData();string old=JsonConvert.SerializeObject(new object[]{w.StudioHeist,w.Custody});var r=Drive(w);r.Pulse();HalloweenTransactions.Checkpoint(w,"ride",r.Progress,()=>{},out _);Assert.Equal(88,(int)w.Halloween.Pending.Progress.Extra["FutureProgress"]);Assert.Equal(77,(int)w.Halloween.Pending.Options.Extra["FutureOptions"]);HalloweenTransactions.Finish(w,"ride","interrupted",50,null,()=>{},out _);Assert.Equal(42,(int)w.Extra["FutureWallet"]);Assert.Equal("keep",(string)w.Halloween.Extra["FutureBook"]);Assert.Equal(old,JsonConvert.SerializeObject(new object[]{w.StudioHeist,w.Custody}));}
        [Fact]public void HistoryIsBoundedAndLifetimeTotalsRetained(){var w=W();for(int i=0;i<40;i++){string id="ride"+i;HalloweenTransactions.Begin(w,id,C(),()=>{},out _);Assert.True(HalloweenTransactions.Finish(w,id,"interrupted",0,null,()=>{},out _));}Assert.Equal(32,w.Halloween.History.Count);Assert.Equal(40,w.Halloween.Started);Assert.Equal(40,w.Halloween.Interrupted);Assert.True(w.Halloween.Valid);}
        [Fact]public void InvalidConfigAndCorruptJournalStayProtected(){var c=C();c.MaxAttackers=7;Assert.False(c.Valid);Assert.False(HalloweenTransactions.Begin(W(),"bad",c,()=>throw new Exception(),out _));var w=Begin();w.Halloween.TotalPulses=-1;Assert.False(w.Halloween.Valid);Assert.False(HalloweenTransactions.Finish(w,"ride","interrupted",0,null,()=>throw new Exception(),out _));w=Begin();w.Halloween.History=null;Assert.False(w.Halloween.Valid);}
        [Fact]public void CounterOverflowRefusesNewRunOrPulseWithoutPartialWrite(){var w=W();w.Halloween=new HalloweenData{Started=long.MaxValue,Interrupted=long.MaxValue};Assert.True(w.Halloween.Valid);Assert.False(HalloweenTransactions.Begin(w,"overflow",C(),()=>throw new Exception(),out _));w=Begin();var r=Drive(w);w.Halloween.TotalPulses=long.MaxValue;r.Pulse();Assert.False(HalloweenTransactions.Checkpoint(w,"ride",r.Progress,()=>throw new Exception(),out _));Assert.Equal(0,w.Halloween.Pending.Progress.Pulses);}
        [Theory][InlineData(0,27)][InlineData(12,17.55f)][InlineData(12.1f,0)][InlineData(-1,0)][InlineData(float.NaN,0)]
        public void PulseFalloffMatchesReferenceAndRejectsOutsideRange(float distance,float expected){Assert.Equal(expected,HalloweenRules.PulseSpeed(C(),distance),3);}
        [Fact]public void PulseNeverTouchesAmbientForeignOccupiedConnectedOrAirborneCars(){var c=C();Assert.True(HalloweenRules.PulseTarget(true,true,true,false,false,false,12,c));Assert.False(HalloweenRules.PulseTarget(false,true,true,false,false,false,1,c));Assert.False(HalloweenRules.PulseTarget(true,false,true,false,false,false,1,c));Assert.False(HalloweenRules.PulseTarget(true,true,false,false,false,false,1,c));Assert.False(HalloweenRules.PulseTarget(true,true,true,true,false,false,1,c));Assert.False(HalloweenRules.PulseTarget(true,true,true,false,true,false,1,c));Assert.False(HalloweenRules.PulseTarget(true,true,true,false,false,true,1,c));}
        [Theory][InlineData(1000,800,80)][InlineData(-1,800,0)][InlineData(1200,1100,100)][InlineData(float.NaN,1000,0)]
        public void ConditionUsesWorseEngineOrBodyAndClamps(float body,float engine,float expected){Assert.Equal(expected,HalloweenRules.Condition(body,engine));}
        [Fact]public void HalloweenSharesExclusiveGateWithPoliceHeistAndJobs(){var g=new ShiftGate();Assert.True(g.Acquire("halloween"));foreach(string n in new[]{"studio_heist","traffic","custody","pizza","pilot"})Assert.False(g.Acquire(n));g.Release("other");Assert.Equal("halloween",g.Owner);g.Release("halloween");Assert.True(g.Acquire("studio_heist"));}
    }
}
